def rle(s):
    if not s:
        return ''
    out = []
    prev = s[0]
    cnt = 1
    for ch in s[1:]:
        if ch == prev:
            cnt += 1
        else:
            out.append(str(cnt) + prev)
            prev = ch
            cnt = 1
    out.append(str(cnt) + prev)
    return ''.join(out)
